using Finora.Domain;using Microsoft.EntityFrameworkCore;namespace Finora.Infrastructure;public sealed class FinoraDbContext(DbContextOptions<FinoraDbContext> options):DbContext(options){public DbSet<Account> Accounts=>Set<Account>();public DbSet<FinanceTransaction> Transactions=>Set<FinanceTransaction>();public DbSet<TransactionSplit> TransactionSplits=>Set<TransactionSplit>();public DbSet<Category> Categories=>Set<Category>();public DbSet<Tag> Tags=>Set<Tag>();public DbSet<TransactionTag> TransactionTags=>Set<TransactionTag>();public DbSet<Budget> Budgets=>Set<Budget>();public DbSet<BudgetPeriod> BudgetPeriods=>Set<BudgetPeriod>();public DbSet<SavingsGoal> SavingsGoals=>Set<SavingsGoal>();public DbSet<GoalContribution> GoalContributions=>Set<GoalContribution>();public DbSet<RecurrenceRule> RecurrenceRules=>Set<RecurrenceRule>();public DbSet<RecurrenceOccurrence> RecurrenceOccurrences=>Set<RecurrenceOccurrence>();public DbSet<Attachment> Attachments=>Set<Attachment>();public DbSet<AppSetting> AppSettings=>Set<AppSetting>();public DbSet<AuditEntry> AuditEntries=>Set<AuditEntry>();public DbSet<BackupMetadata> BackupMetadata=>Set<BackupMetadata>();protected override void OnModelCreating(ModelBuilder b){b.Entity<TransactionTag>().HasKey(x=>new{x.TransactionId,x.TagId});b.Entity<Category>().HasOne(x=>x.Parent).WithMany(x=>x.Children).HasForeignKey(x=>x.ParentId).OnDelete(DeleteBehavior.Restrict);b.Entity<RecurrenceOccurrence>().HasIndex(x=>new{x.RecurrenceRuleId,x.DueOn}).IsUnique();b.Entity<AppSetting>().HasIndex(x=>x.Key).IsUnique();b.Entity<BackupMetadata>().HasIndex(x=>x.BackupId).IsUnique();b.Entity<FinanceTransaction>().HasIndex(x=>new{x.AccountId,x.OccurredAtUtc});b.Entity<FinanceTransaction>().HasIndex(x=>x.TransferGroupId);}}
